add_action('init', function () {
    $page = get_page_by_path('privacy', OBJECT, 'page');
    if (!$page) {
        $page_id = wp_insert_post(array(
            'post_title'   => 'Privacy',
            'post_name'    => 'privacy',
            'post_content' => gb_privacy_policy_content(),
            'post_status'  => 'publish',
            'post_type'    => 'page',
        ));
        if (!is_wp_error($page_id)) {
            update_option('wp_page_for_privacy_policy', (int) $page_id);
        }
    } else {
        update_option('wp_page_for_privacy_policy', (int) $page->ID);
    }
}, 45);

